      {"country": "Mali", "income_group": "Low", "gdp_per_capita_usd": 830, "hdi": 0.428, "freedom_index": 22, "corruption_perceptions_index": 28, "co2_emissions_per_capita_tons": 0.1, "military_expenditure_pct_gdp": 3.5, "internet_penetration_pct": 34},
      {"country": "Chad", "income_group": "Low", "gdp_per_capita_usd": 690, "hdi": 0.394, "freedom_index": 15, "corruption_perceptions_index": 20, "co2_emissions_per_capita_tons": 0.1, "military_expenditure_pct_gdp": 2.9, "internet_penetration_pct": 14},
      {"country": "Afghanistan", "income_group": "Low", "gdp_per_capita_usd": 380, "hdi": 0.462, "freedom_index": 8, "corruption_perceptions_index": 24, "co2_emissions_per_capita_tons": 0.3, "military_expenditure_pct_gdp": 3.3, "internet_penetration_pct": 18}
    ];

    var dimensions = [
      "gdp_per_capita_usd",
      "hdi",
      "freedom_index",
      "corruption_perceptions_index",
      "co2_emissions_per_capita_tons",
      "military_expenditure_pct_gdp",
      "internet_penetration_pct"
    ];

    var dimensionLabels = {
      "gdp_per_capita_usd": "GDP per capita ($)",
      "hdi": "Human Dev. Index",
      "freedom_index": "Freedom Index",
      "corruption_perceptions_index": "Corruption Index",
      "co2_emissions_per_capita_tons": "CO2/Capita (tons)",
      "military_expenditure_pct_gdp": "Military Exp. (% GDP)",
      "internet_penetration_pct": "Internet Pen. (%)"
    };

    var colorMap = {
      "High": "#2563eb",         
      "Upper-Middle": "#059669", 
      "Lower-Middle": "#d97706", 
      "Low": "#e11d48"           
    };

    function buildChart() {
      if (typeof d3 === 'undefined') {
        setTimeout(buildChart, 100);
        return;
      }

      d3.select("#chart-container").selectAll("*").remove();

      var container = document.getElementById('chart-container');
      var width = container.clientWidth;
      var height = container.clientHeight;
      var margin = {top: 40, right: 90, bottom: 20, left: 70};

      var svg = d3.select("#chart-container")
        .append("svg")
        .attr("width", width)
        .attr("height", height)
        .append("g")
        .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

      var innerWidth = width - margin.left - margin.right;
      var innerHeight = height - margin.top - margin.bottom;

      var y = {};
      for (var i = 0; i < dimensions.length; i++) {
        var name = dimensions[i];
        y[name] = d3.scaleLinear()
          .domain(d3.extent(data, function(d) { return +d[name]; }))
          .range([innerHeight, 0]);
      }

      var x = d3.scalePoint()
        .range([0, innerWidth])
        .padding(0.05)
        .domain(dimensions);

      function path(d) {
        return d3.line()(dimensions.map(function(p) { return [x(p), y[p](d[p])]; }));
      }

      var outliers = ["Saudi Arabia", "United Arab Emirates", "China", "Russia", "United States", "Norway"];

      svg.selectAll("myPath")
        .data(data)
        .enter()
        .append("path")
        .attr("d", path)
        .style("fill", "none")
        .style("stroke", function(d) { return colorMap[d.income_group]; })
        .style("opacity", function(d) { return outliers.includes(d.country) ? 0.9 : 0.35; })
        .style("stroke-width", function(d) { return outliers.includes(d.country) ? 3 : 1.5; })
        .style("transition", "all 0.2s");

      dimensions.forEach(function(dim) {
        svg.selectAll(".dot-" + dim)
          .data(data)
          .enter()
          .append("circle")
          .attr("cx", x(dim))
          .attr("cy", function(d) { return y[dim](d[dim]); })
          .attr("r", function(d) { return outliers.includes(d.country) ? 4.5 : 2.5; })
          .style("fill", function(d) { return colorMap[d.income_group]; })
          .style("opacity", function(d) { return outliers.includes(d.country) ? 1 : 0.5; });
      });

      var axes = svg.selectAll("myAxis")
        .data(dimensions).enter()
        .append("g")
        .attr("transform", function(d) { return "translate(" + x(d) + ")"; })
        .each(function(d) { 
          d3.select(this).call(d3.axisLeft().scale(y[d]).ticks(8).tickFormat(d3.format("~s"))); 
        });

      axes.selectAll("path, line")
        .style("stroke", "var(--border)")
        .style("stroke-width", "1.5px");

      axes.selectAll("text")
        .style("fill", "var(--text-secondary)")
        .style("font-size", "12px")
        .style("font-family", "Inter");

      axes.append("text")
        .style("text-anchor", "middle")
        .attr("y", -24)
        .text(function(d) { return dimensionLabels[d]; })
        .style("fill", "var(--text)")
        .style("font-size", "14px")
        .style("font-weight", 600)
        .style("font-family", "Inter");

      var outlierLabels = [
        { country: "Saudi Arabia", dim: "co2_emissions_per_capita_tons", align: "start", dx: 8, dy: 14 },
        { country: "United Arab Emirates", dim: "co2_emissions_per_capita_tons", align: "start", dx: 8, dy: -4 },
        { country: "China", dim: "freedom_index", align: "start", dx: 8, dy: 4 },
        { country: "Russia", dim: "corruption_perceptions_index", align: "start", dx: 8, dy: 4 },
        { country: "United States", dim: "gdp_per_capita_usd", align: "end", dx: -8, dy: 4 },
        { country: "Norway", dim: "hdi", align: "start", dx: 8, dy: 0 }
      ];

      svg.selectAll(".outlierLabel")
        .data(outlierLabels)
        .enter()
        .append("text")
        .attr("x", function(d) { return x(d.dim) + d.dx; })
        .attr("y", function(d) { 
          var row = data.find(r => r.country === d.country);
          return y[d.dim](row[d.dim]) + d.dy; 
        })
        .text(function(d) { return d.country; })
        .style("text-anchor", function(d) { return d.align; })
        .style("fill", function(d) { 
          var row = data.find(r => r.country === d.country);
          return colorMap[row.income_group]; 
        })
        .style("font-size", "14px")
        .style("font-weight", 700)
        .style("font-family", "Inter")
        .style("pointer-events", "none")
        .style("text-shadow", "0px 1px 3px rgba(255,255,255,0.9)");
    }

    document.addEventListener("DOMContentLoaded", buildChart);
    window.addEventListener("resize", buildChart);
    function onThemeChange() { buildChart(); }
  </script>
</body>
</html>
